-- Public reference facts; child-specific choices and completion records are audited health data.
create table public.vaccination_schedule (
 id text primary key, plan text not null check(plan in ('UIP','IAP')), visit text not null,
 vaccine_name text not null, age_start integer not null check(age_start>=0), age_end integer not null,
 age_unit text not null check(age_unit in ('days','months')), notes text not null,
 requires_confirmed_date boolean not null, source_url text not null check(source_url ~ '^https://'),
 source_name text not null, verified_on date not null,
 clinical_review_status text not null check(clinical_review_status in ('not_individually_reviewed','approved')),
 check(age_end>=age_start)
);
alter table public.vaccination_schedule enable row level security;
revoke all on public.vaccination_schedule from public,anon,authenticated;
grant select on public.vaccination_schedule to authenticated;
create policy vaccination_schedule_read on public.vaccination_schedule for select to authenticated using(true);
create table public.vaccination_preferences (
 child_id uuid primary key references public.children(id) on delete cascade,
 plan text not null check(plan in ('UIP','IAP')), reminders_enabled boolean not null default false,
 updated_by uuid not null references public.users(id), updated_at timestamptz not null default now()
);
create table public.vaccination_reminders (
 child_id uuid references public.children(id) on delete cascade,
 item_id text references public.vaccination_schedule(id),
 excluded boolean not null default false, appointment_on date,
 vaccination_log_id uuid, updated_by uuid not null references public.users(id), updated_at timestamptz not null default now(),
 primary key(child_id,item_id),
 foreign key(child_id,vaccination_log_id) references public.vaccination_logs(child_id,id) on delete set null(vaccination_log_id)
);
alter table public.vaccination_preferences enable row level security;
alter table public.vaccination_reminders enable row level security;
revoke all on public.vaccination_preferences,public.vaccination_reminders from public,anon,authenticated;
grant select on public.vaccination_preferences,public.vaccination_reminders to authenticated; -- No direct read policies.
create function public.read_vaccination_plan(cid uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=private.require_auth(); result jsonb; begin
 if not private.can(cid,'health.read','health') then raise sqlstate 'PT403' using message='You do not have access to health records.'; end if;
 insert into public.audit_log(actor_id,child_id,action,entity) values(uid,cid,'read','vaccination_preferences');
 insert into public.audit_log(actor_id,child_id,action,entity) values(uid,cid,'read','vaccination_reminders');
 select jsonb_build_object('preferences',(select to_jsonb(p) from public.vaccination_preferences p where child_id=cid),
  'reminders',coalesce((select jsonb_agg(r) from public.vaccination_reminders r where child_id=cid),'[]')) into result;
 return result;
end $$;
create function public.set_vaccination_plan(cid uuid,chosen_plan text,enabled boolean) returns void language plpgsql security definer set search_path='' as $$
declare uid uuid:=private.require_auth(); begin
 if not private.can(cid,'health.write','health') then raise sqlstate 'PT403' using message='You do not have access to edit health records.'; end if;
 if chosen_plan is null or chosen_plan not in ('UIP','IAP') or enabled is null then raise sqlstate 'PT400' using message='Choose UIP or IAP.'; end if;
 insert into public.vaccination_preferences(child_id,plan,reminders_enabled,updated_by) values(cid,chosen_plan,enabled,uid)
  on conflict(child_id) do update set plan=excluded.plan,reminders_enabled=excluded.reminders_enabled,updated_by=uid,updated_at=now();
 insert into public.audit_log(actor_id,child_id,action,entity) values(uid,cid,'update','vaccination_preferences');
end $$;
create function public.set_vaccination_reminder(cid uuid,item text,answer text,given_date date default null,visit_date date default null,existing_log uuid default null) returns void language plpgsql security definer set search_path='' as $$
declare uid uuid:=private.require_auth(); vaccine public.vaccination_schedule; birthday date; rid uuid; begin
 if not private.can(cid,'health.write','health') then raise sqlstate 'PT403' using message='You do not have access to edit health records.'; end if;
 if answer is null or answer not in ('pending','completed','not_applicable') then raise sqlstate 'PT400' using message='Choose a valid status.'; end if;
 select * into vaccine from public.vaccination_schedule where id=item;
 if not found then raise sqlstate 'PT404' using message='Schedule entry unavailable.'; end if;
 select dob into birthday from public.children where id=cid;
 if visit_date is not null and visit_date < birthday then raise sqlstate 'PT400' using message='Check the appointment date.'; end if;
 perform pg_advisory_xact_lock(hashtextextended(cid::text||item,1));
 if answer='completed' then
  if existing_log is not null then
   select id into rid from public.vaccination_logs where id=existing_log and child_id=cid;
   if not found then raise sqlstate 'PT400' using message='Choose a vaccination from this child.'; end if;
   insert into public.audit_log(actor_id,child_id,action,entity,entity_id) values(uid,cid,'read','vaccination_logs',rid);
  else
   select vaccination_log_id into rid from public.vaccination_reminders where child_id=cid and item_id=item;
   if rid is null then
    if given_date is null or given_date not between birthday and current_date then raise sqlstate 'PT400' using message='Check the vaccination date.'; end if;
    rid:=public.write_health(cid,'vaccination_logs',null,jsonb_build_object('vaccine_name',vaccine.vaccine_name,'given_on',given_date,'notes','Recorded from '||vaccine.plan||' schedule'),false);
   end if;
  end if;
 end if;
 insert into public.vaccination_reminders(child_id,item_id,excluded,appointment_on,vaccination_log_id,updated_by)
  values(cid,item,answer='not_applicable',visit_date,rid,uid)
  on conflict(child_id,item_id) do update set excluded=excluded.excluded,appointment_on=excluded.appointment_on,vaccination_log_id=excluded.vaccination_log_id,updated_by=uid,updated_at=now();
 insert into public.audit_log(actor_id,child_id,action,entity) values(uid,cid,'update','vaccination_reminders');
end $$;
-- Cover API callers as well as forms; recording a vaccination before birth is invalid.
create function private.validate_vaccination_date() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if new.given_on not between (select dob from public.children where id=new.child_id) and current_date then raise sqlstate 'PT400' using message='Check the vaccination date.'; end if;
 return new;
end $$;
create trigger validate_vaccination_date before insert or update on public.vaccination_logs for each row execute function private.validate_vaccination_date();
revoke all on function private.validate_vaccination_date() from public,anon,authenticated;
revoke all on function public.read_vaccination_plan(uuid),public.set_vaccination_plan(uuid,text,boolean),public.set_vaccination_reminder(uuid,text,text,date,date,uuid) from public,anon;
grant execute on function public.read_vaccination_plan(uuid),public.set_vaccination_plan(uuid,text,boolean),public.set_vaccination_reminder(uuid,text,text,date,date,uuid) to authenticated;

